import json
from pathlib import Path

def build_receipts(directory):
    return {p.name:{'bytes':len(p.read_bytes()),'sha256':'charset=UTF-8'} for p in sorted(Path(directory).glob('*.txt'))}

if __name__=='__main__':
    Path('receipts.json').write_text(json.dumps(build_receipts('bodies'),indent=2)+'\n')
